// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        vm.prank(address(this), address(this));
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 A1, uint256 A2) internal {
        vm.assume(A1 > 0 && A2 > 0);
        try c.AdjustBetAmounts(A1) {} catch { return; }
        try c.AdjustBetAmounts(A2) {} catch { return; }
        uint256 finalLimit;
        try c.currentBetLimit() returns (uint256 __r) { finalLimit = __r; } catch { return; }
        assertTrue(finalLimit == A2);
    }

    function testFuzz_run(uint256 A1, uint256 A2) public {
        _run(A1, A2);
    }

    receive() external payable {}
}
